package net.officefloor.hq.app.settings;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.UriUtils;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.ObjectMapper;

/** A viewer sees every screen and can change nothing: every change to a sheet (a POST or PUT under
 *  {@code /api/sheets/<id>/}) by a user who is a viewer on that sheet is refused 400 before it
 *  reaches its pipeline, so it writes nothing and audits nothing. A bulk action still goes through,
 *  each selected item refused by the permission matrix (see {@link Settings#allows}) — a bulk grade
 *  grades no one — so its counts show none done. An archived sheet is guarded the same way for every user. */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ViewerGuard extends OncePerRequestFilter {

    private static final String PREFIX = "/api/sheets/";

    /** The bulk actions, by the path after the sheet id: they answer counts instead of refusing. */
    private static final Set<String> BULK = Set.of("bulk-open", "bulk-settle", "bulk-grade", "bulk-retire");

    private static final ObjectMapper JSON = new ObjectMapper();

    private final Settings settings;
    private final Sheets sheets;

    public ViewerGuard(Settings settings, Sheets sheets) {
        this.settings = settings;
        this.sheets = sheets;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        String method = request.getMethod();
        return !(method.equals("POST") || method.equals("PUT") || method.equals("DELETE"))
                || !request.getRequestURI().startsWith(PREFIX);
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String rest = request.getRequestURI().substring(PREFIX.length());
        int slash = rest.indexOf('/');
    }

    /** The sheet's today, starting the sheet at the real date when it has never been used. */
    public LocalDate today(String sheetId) {
        jdbc.update("MERGE INTO sheet (id, today) KEY (id) SELECT ?, ? FROM DUAL "
                + "WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                sheetId, Date.valueOf(LocalDate.now()), sheetId);
        return jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId)
                .toLocalDate();
    }

    /**
     * The sheet's next claim number: the next after the last number given anywhere in the sheet's
import { useEffect, useRef } from 'react';

// The actions of a person's row (statement, hold, retire) share the row's one error element; taking
// any of them clears the error another left showing, so only the latest action's error remains.
type Listener = { sheet: string; personId: number; owner: object; reset: () => void };
const listeners = new Set<Listener>();

/** Register a row action's `reset`; the returned `taken` is called as the action is taken. */
export function useRowAction(sheet: string, personId: number, reset: () => void): () => void {
  const owner = useRef({}).current;
  const resetRef = useRef(reset);
  resetRef.current = reset;
  useEffect(() => {
    const l: Listener = { sheet, personId, owner, reset: () => resetRef.current() };
    listeners.add(l);
    return () => {
      listeners.delete(l);
    };
  }, [sheet, personId, owner]);
  return () => {
    for (const l of listeners) {
      if (l.owner !== owner && l.sheet === sheet && l.personId === personId) l.reset();
    }
  };
}

